function resetGame(seed) {
  rng = mulberry32(seed);
  score = 0;
  lives = 1;
  gameState = 'PLAYING';

  player = { x: 60, y: 200, w: 20, h: 20, vy: 0 };
  coins = [];
  zappers = [];
  distance = 0;
  nextSpawnDist = 150; 
  frames = 0;

  particles = [];
  initEnvironment();
}
